//! Golden corpus for the `tld` -> `psl` port behind `base_url`.
//!
//! `testdata/tld_base_urls.jsonl` is generated by `tools/gen_base_urls.py`,
//! which runs the reference implementation's own `StorageSystemMixin.__init__` +
//! `_get_base_url()` under CPython with the real `tld` package. Every line is
//! `{"url": <constructor argument>, "expected": <namespace>}`.
//!
//! This is a required gate, not a nicety: `base_url` is the *first* column of
//! the `(url, identifier)` primary key, so a single disagreement with Python
//! silently partitions an `elements_storage.db` into two halves that cannot see
//! each other's rows. The corpus covers the whole decision tree — the
//! `fix_protocol` prepend, `urlsplit`'s host extraction, multi-label and
//! private public suffixes, wildcard and exception rules, hosts that *are* a
//! suffix, unknown suffixes, IP literals, IDN, and the empty/`None` fallbacks.

use std::fs;
use std::path::PathBuf;

use browser_storage::base_url::registrable_domain;
use browser_storage::r#trait::StorageSystem;
use browser_storage::sqlite::SqliteStorage;

fn corpus_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("testdata/tld_base_urls.jsonl")
}

/// `(url, expected)` pairs; a JSON `null` url means "constructed with `None`".
fn corpus() -> Vec<(Option<String>, String)> {
    let path = corpus_path();
    let text =
        fs::read_to_string(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));

    let mut cases = Vec::new();
    for (lineno, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let case: serde_json::Value = serde_json::from_str(line)
            .unwrap_or_else(|e| panic!("{}:{}: bad JSON: {e}", path.display(), lineno + 1));

        let url = match &case["url"] {
            serde_json::Value::Null => None,
            serde_json::Value::String(url) => Some(url.clone()),
            other => panic!("{}:{}: unexpected url {other}", path.display(), lineno + 1),
        };
        let expected = case["expected"]
            .as_str()
            .unwrap_or_else(|| panic!("{}:{}: missing expected", path.display(), lineno + 1))
            .to_owned();
        cases.push((url, expected));
    }
    assert!(
        cases.len() >= 70,
        "the corpus lost cases: only {} left",
        cases.len(),
    );
    cases
}

#[test]
fn matches_tld_on_every_golden_case() {
    for (url, expected) in corpus() {
        let got = registrable_domain(url.as_deref());
        assert_eq!(
            got, expected,
            "registrable_domain({url:?}) = {got:?}, the reference implementation's tld says {expected:?}",
        );
    }
}

#[test]
fn the_storage_namespace_matches_the_golden_case() {
    // The same corpus, but read back through the constructor — this is the
    // value that actually reaches the `url` column.
    for (url, expected) in corpus() {
        let storage = SqliteStorage::in_memory(url.as_deref()).expect("open");
        assert_eq!(
            storage.base_url(),
            expected,
            "SqliteStorage::in_memory({url:?}).base_url()",
        );
        assert_eq!(StorageSystem::base_url(&storage), expected);
    }
}

#[test]
fn the_corpus_covers_every_branch_of_the_fallback_chain() {
    let cases = corpus();

    let defaults = cases.iter().filter(|(_, e)| e == "default").count();
    assert!(defaults >= 10, "too few unresolvable URLs: {defaults}");

    // A host that is itself a public suffix returns the suffix (`fld == tld`).
    assert!(cases
        .iter()
        .any(|(url, expected)| url.as_deref() == Some("https://com") && expected == "com"));

    // The private section of the list is in play.
    assert!(cases.iter().any(|(url, expected)| {
        url.as_deref() == Some("https://a.blogspot.com") && expected == "a.blogspot.com"
    }));

    // `fix_protocol` really is exercised by a bare domain.
    assert!(cases
        .iter()
        .any(|(url, expected)| url.as_deref() == Some("example.com") && expected == "example.com"));
}
